const jumlahHariSurat = (mulai, selesai) => {
  if (!mulai) return 1;
  const a = new Date(mulai + "T00:00:00"); const b = new Date((selesai || mulai) + "T00:00:00");
  return Math.max(1, Math.round((b - a) / 86400000) + 1);
};


